    c.save();
    c.translate(x, y);
    c.scale(size / 24, size / 24);
    c.strokeStyle = color;
    c.lineWidth = 1.7; c.lineCap = 'round'; c.lineJoin = 'round';
    var re = /<(path|rect|circle)\b([^>]*)\/?>/g, m;
