      var p = new Path2D();
      if (m[1] === 'path') p = new Path2D(get('d'));
      else if (m[1] === 'rect') p.rect(parseFloat(get('x')), parseFloat(get('y')), parseFloat(get('width')), parseFloat(get('height')));
